import logging
import re
import time
from typing import Optional, Union

from .exceptions import (SWMOperationFailedException,
                         SWMOperationTimeoutException)
from .swm_command import SwmCommand

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SwmOperations:

    def __init__(self, was_node):
        self.was_node = was_node

    def get_mo_status(self, dist_names):
        """
        Gets all values from mo-status command output for given dist_names.

        **NOTE: The swmCLI.sh is available since NetAct18 SP06, so this functionality is supported since then as well.**

        **Example output:**

        ::

            {
                "PLMN-PLMN/MRBTS-12345": {
                    "planned_sw": "",
                    "last_backup": "",
                    "last_upload": "26.03.2019 06:17:06",
                    "active_sw": "FL19_ENB_0000_000092_000000",
                    "last_active_op": "NotificationUpload",
                    "mo_name": "",
                    "release": "FL19",
                    "passive_sw": "FL19_ENB_0000_000146_000000",
                    "last_op_status": "SUCCESS"
                },
                "PLMN-PLMN/MRBTS-54321": {
                    "planned_sw": "",
                    "last_backup": "",
                    "last_upload": "22.03.2019 09:41:08",
                    "active_sw": "FL18A_ENB_0000_010080_000210",
                    "last_active_op": "SWProvision",
                    "mo_name": "",
                    "release": "FL18A",
                    "passive_sw": "FL19_ENB_0000_000139_000000",
                    "last_op_status": "FAILED"
                }
            }

        :param (string|list(string)) dist_names: Specifies the scope of the operation,
             e.g. PLMN-PLMN/MRBTS-12345 or [PLMN-PLMN/MRBTS-12345, PLMN-PLMN/MRBTS-54321]
        :rtype: dict(string, dict(string, string))
        :return: Dictionary containing dist_names with corresponding values returned by mo-status command.
        """
        command = SwmCommand(
            options={
                '--operation': 'mo-status',
                '-dn': dist_names
            }
        )

        with self.was_node as ssh:
            output = ssh.execute_command(command.text).stdout
        if 'client certification creation failed' in output.lower():
            raise SWMOperationFailedException(output)

        logger.debug(f'Raw mo-status:\n{output}')
        result = self._convert_output_to_dict(output)
        self._validate_dist_names(dist_names, result)
        return result

    @staticmethod
    def _convert_output_to_dict(output):
        column_separator = re.compile(r',\s+')
        lines = [column_separator.split(row) for row in output.strip().splitlines()]
        column_names = [column.lower() for column in lines[0]]
        return {line[0]: dict(zip(column_names[1:], line[1:])) for line in lines[1:]}

    @staticmethod
    def _validate_dist_names(dist_names, result):
        dist_names = [dist_names] if not isinstance(dist_names, list) else dist_names
        missing_dist_names = [dist_name for dist_name in dist_names if dist_name not in result.keys()]
        if missing_dist_names:
            raise SWMOperationFailedException(f'Missing dist_names: {missing_dist_names}')

    @classmethod
    def _build_swm_cli_start_command(cls, operation: str,
                                     dist_names: Union[str, list[str]],
                                     package_name: Optional[str] = None,
                                     custom_attributes: Optional[dict] = None
                                     ) -> SwmCommand:

        command = SwmCommand(
            options={
                '--operation': 'start',
                '-t': operation,
                '-dn': dist_names,
                '-s': package_name,
                '-c': custom_attributes
            }
        )

        return command

    def provision_sw(self, dist_names, package_name, timeout=600):
        """
        Execute provision operation on given MO.

        :param (string|list(string)) dist_names: Specifies the scope of the operation, e.g. MRBTS-12345
            or [PLMN-PLMN/MRBTS-12345, PLMN-PLMN/MRBTS-54321]
        :param package_name: for example FL00_FSM4_9999_170924_017511, WBTS16_0000_001454_000005, etc.
        :param timeout: for how long check if operation completed
        :return: operation status
        """
        with self.was_node:
            operation_id = self.start_swm_operation('provision', dist_names, package_name)
            self.wait_for_swm_operation(operation_id, timeout)
            return self._get_operation_status(operation_id)

