    def start_swm_operation(self, operation_type, dist_names, package=None, custom_attributes=None):
        """
        Starts given SWM operation with CLI. Available operation types:

        Operation types:
        ****************
        ::
            upload, download, precheck, prepare, activation, provision, postcheck, rollback, commit,
            upload-backup-list, bf, bf-ext, bf-nms, bp, bp-ext, bp-nms, bc, bc-nms

        :param operation_type: e.g. download
        :param (string|list(string)) dist_names: managed object, for example MRBTS-100774,
            or [PLMN-PLMN/MRBTS-12345, PLMN-PLMN/MRBTS-54321]
        :param package: (optional) e.g. SBTS20C_ENB_9999_201218_000009
        :param string custom_attributes: Custom attributes that will be used
            for the operation, represented as a dictionary, e.g., {'precheckType': 'fullCheck'}.
            A list of values is expected for multi-valued custom attributs, i.e.,
            {'single': 'value', 'multiple': ['value1', 'value2']}
        :return: operation identifier, e.g., op_id_123
        """
        return self._start_swm_operation(operation_type, dist_names, package, custom_attributes)

    def _start_swm_operation(self, operation_type, dist_names, package=None, custom_attributes=None):
        """
        :param operation_type: e.g. download
        :param (string|list(string)) dist_names: managed object, for example MRBTS-100774,
            or a list [PLMN-PLMN/MRBTS-12345, PLMN-PLMN/MRBTS-54321]
        :param package: (optional) e.g. SBTS20C_ENB_9999_201218_000009
        :param dict custom_attributes: Custom attributes that will be used
            for the operation, represented as a dictionary, e.g., {'precheckType': 'fullCheck'},
            A list of values is expected for multi-valued custom attributs, i.e.,
            {'single': 'value', 'multiple': ['value1', 'value2']}
        :return: operation identifier, e.g., op_id_123
        """
        logger.info(f'Starting {operation_type}...')

        command = self._build_swm_cli_start_command(operation_type, dist_names, package, custom_attributes)
        logger.info(f'Running command:\n{command.text}')
        with self.was_node as ssh:
            operation_id = ssh.execute_command(command.text).stdout
        logger.debug(f'Identifier for {operation_type}: {operation_id}')

        if not operation_id.startswith('op_id'):
            raise SWMOperationFailedException(operation_id)

        return operation_id

    def get_progress_of_swm_operation(self, operation_id):
        """
        Get status of given operation determined by operation ID

        :param operation_id: e.g. 'op_id_123'
        :return: a dictionary with output of CLI's operation-summary procedure


        example output of 'operation-summary':

        Status: Partially failed
        Task Type: Upload
        Created by: OMC
        Creation date: 2016-09-01 15:15:45
        Start date: 2016-09-01 15:15:47
        End date: 2016-09-01 15:17:29
        Queued: 0
        Ongoing: 0
        Successful: 1
        Failed: 2
        Canceled: 0
        Canceling: 0
        Resuming: 0
        Retrying last step: 0
        Total: 3
        """
        command = SwmCommand(
            options={
                '--operation': 'operation-summary',
                '-id': operation_id
            }
        )
        with self.was_node as ssh:
            output = ssh.execute_command(command.text).stdout
        logger.debug(output)

        summary_dict = dict(line.split(': ') for line in output.splitlines())
        return summary_dict

    def _get_operation_status(self, operation_id):
        status = self.get_progress_of_swm_operation(operation_id).get('Status')
        if 'failed' in status.lower():
            raise SWMOperationFailedException(f'Status: {status}')
        return status

    def wait_for_swm_operation(self, operation_id, timeout, interval=10):
        """
        Waits for the operation to complete with given timeout.

        :param operation_id: e.g. op_id_123
        :param timeout: Timeout in seconds, e.g. 60
        :param interval: Wait time between consecutive checks
        :return: ``True`` if operation completed in time, else raise an exception


        example output of 'ongoing-operations':

        op_id_1234
        op_id_1235
        """
        command = SwmCommand(
            options={'--operation': 'ongoing-operations'}
        )

        start_time = time.monotonic()
        time_elapsed = 0

        with self.was_node as ssh:
            while time_elapsed < timeout:
                time_elapsed = time.monotonic() - start_time
                output = ssh.execute_command(command.text).stdout
                logger.debug(output)

                if operation_id not in output:
                    return True

                time.sleep(interval)  # ???

            if time_elapsed >= timeout:
                msg = f'Operation {operation_id} timed out'
                raise SWMOperationTimeoutException(msg)

    def cancel_swm_operation(self, operation_id):
        """
        Cancel a triggered operation identified by given operation id.

        :param operation_id: e.g., ``op_id_123``
        """
        command = SwmCommand(
            options={'--operation': 'cancel',
                     '--id': operation_id}
        )

        with self.was_node as ssh:
            output = ssh.execute_command(command.text).stdout
            return output

    def get_mos_list(self, mo_type='MRBTS', maintenance_region=None,
                     working_set=None, parent=None):
        """
        Get network elements of a specific type as FQDNs using `list-mos` operation.

        Software Manager business logic initializes (rebuilds topology data)
        when the `list-mos` operation is launched, if working set name was changed
        or a new network element of chosen MO type was added.

        .. note::
            Only one optional parameter/filter can be defined:
            ``maintenance_region`` or ``working_set`` or ``parent``

        :param string mo_type: Filter for particular mo-type, e.g. ``MRBTS``
        :param string maintenance_region: (Optional) Filter for particular maintenance-region
        :param string working_set: (Optional) Filter for particular working set by working set name
        :param string parent: (Optional) Filter for particular parent
        :return: Network elements of a specific type as FQDNs
        :rtype: list(string)
        """
        optional_params = ['maintenance_region', 'working_set', 'parent']
        set_optional_params = [k for k, v in locals().items() if k in optional_params and v]
        if len(set_optional_params) > 1:
            exc_msg = f"Only one optional parameter/filter can be defined: {' or '.join(set_optional_params)}"
            raise ValueError(exc_msg)

        command = SwmCommand(
            options={
                '--operation': 'list-mos',
                '-m': mo_type,
                '-mr': maintenance_region,
                '-w': working_set,
                '-p': parent,
            }
        )
        with self.was_node as ssh:
            output = ssh.execute_command(command.text).stdout
            mos = output.split(',') if output else []
            return mos
